import { buildSearchText } from "../../indexer/search/search-fields.js";
import { getMeta, setMeta } from "./index-meta-repository.js";
import { SQLITE_CHUNK_SIZE } from "./index-sql.js";
/**
 * The embedding model whose vectors this index currently serves: the provider
 * fingerprint the last embedding pass targeted (`index_meta.embeddingFingerprint`).
 * `undefined` on an index that has never run an embedding pass.
 */
function currentEmbeddingModel(db) {
    return getMeta(db, "embeddingFingerprint");
}
const modelColumnPresent = new WeakMap();
/**
 * Whether `embeddings` carries the per-row `model` column. A read-only open of
 * an index the writable opener has not migrated yet does not; its rows are
 * then all served as the current model. Only a positive answer is memoized:
 * the column can appear on a live connection (`ensureSchema`), never vanish.
 */
function hasModelColumn(db) {
    if (modelColumnPresent.get(db) === true)
        return true;
    let present = false;
    try {
        present = db.prepare("PRAGMA table_info(embeddings)").all().some((column) => column.name === "model");
    }
    catch {
        present = false;
    }
    if (present)
        modelColumnPresent.set(db, true);
    return present;
}
/**
 * SQL predicate selecting `embeddings` rows usable for `model`. A NULL model
 * predates per-row model tracking and is trusted as the current model; when
 * no model is known at all, or the index predates the column, every row
 * qualifies.
 */
function modelPredicate(db, model, alias = "embeddings") {
    if (model === undefined || !hasModelColumn(db))
        return { sql: "1", params: [] };
    return { sql: `(${alias}.model IS NULL OR ${alias}.model = ?)`, params: [model] };
}
/** Remove the vector of an entry whose embedding input changed. */
export function deleteEntryVectors(db, id) {
    db.prepare("DELETE FROM embeddings WHERE id = ?").run(id);
}
/**
 * Purge every stored vector and mark the index as embedding-free. Only the
 * explicit `akm index --reembed` override calls this: a model or dimension
 * change keeps every stored row (each carries its own model) and re-embeds
 * incrementally.
 */
export function purgeEmbeddings(db) {
    db.exec("DELETE FROM embeddings");
    setMeta(db, "hasEmbeddings", "0");
}
/**
 * Store one entry's vector. `model` is the provider fingerprint it was
 * generated under (`deriveSemanticProviderFingerprint`); a row written without
 * one is trusted as the current model. Returns false, writing nothing, when
 * the entry no longer exists.
 */
export function upsertEmbedding(db, entryId, embedding, model) {
    // Pre-flight FK guard: when an entry is deleted between when its id is queued
    // for embedding and when this INSERT runs (e.g. consolidation deletes during
    // a concurrent improve cycle), the INSERT throws "FOREIGN KEY constraint failed"
    // and rolls back the entire batch transaction in the caller, losing every
    // embedding for that run. A cheap SELECT here turns the race into a clean skip.
    if (!db.prepare("SELECT 1 FROM entries WHERE id = ?").get(entryId))
        return false;
    db.prepare("INSERT OR REPLACE INTO embeddings (id, embedding, model) VALUES (?, ?, ?)").run(entryId, Buffer.from(new Float32Array(embedding).buffer), model ?? null);
    return true;
}
/**
 * The `k` stored vectors nearest to `query` by cosine similarity, best first
 * (ties by id): an exact scan of the current model's rows. `distance` is
 * `sqrt(2 * (1 - cosine))`, the L2 distance between the unit-normalised
 * vectors. Rows of another width, left by a model that is no longer current,
 * never match. With a `scope`, only that bundle's entries of that type are
 * scanned: the `k` nearest of those, not the `k` nearest of everything filtered
 * afterwards.
 */
export function searchVec(db, query, k, scope, filterCandidates) {
    const dim = query.length;
    const q = Float64Array.from(query);
    let queryNorm = 0;
    for (let i = 0; i < dim; i++)
        queryNorm += q[i] * q[i];
    if (k <= 0 || queryNorm === 0)
        return [];
    queryNorm = Math.sqrt(queryNorm);
    const current = modelPredicate(db, currentEmbeddingModel(db));
    const scoped = scope ? " AND embeddings.id IN (SELECT id FROM entries WHERE type = ? AND bundle_id = ?)" : "";
    const params = scope ? [...current.params, scope.type, scope.bundleId] : current.params;
    const ids = [];
    const similarities = [];
    const rows = db
        .prepare(`SELECT id, embedding FROM embeddings WHERE ${current.sql}${scoped}`)
        .iterate(...params);
    for (const { id, embedding } of rows) {
        if (embedding.byteLength !== dim * 4)
            continue;
        // A Float32Array view needs 4-byte alignment; copy the rare row that lacks it.
        const vector = embedding.byteOffset % 4 === 0
            ? new Float32Array(embedding.buffer, embedding.byteOffset, dim)
            : new Float32Array(embedding.slice().buffer);
        let dot = 0;
        let norm = 0;
        for (let i = 0; i < dim; i++) {
            const x = vector[i];
            dot += x * q[i];
            norm += x * x;
        }
        if (norm === 0)
            continue;
        ids.push(id);
        similarities.push(dot / (Math.sqrt(norm) * queryNorm));
    }
    const order = ids.map((_, index) => index);
    order.sort((a, b) => similarities[b] - similarities[a] || ids[a] - ids[b]);
    const result = (index) => ({
        id: ids[index],
        distance: Math.sqrt(2 * Math.max(0, 1 - similarities[index])),
    });
    if (!filterCandidates)
        return order.slice(0, k).map(result);
    // Filter in similarity order, a batch at a time, so only the rows near the
    // top are loaded and checked — not every embedded entry.
    const results = [];
    for (let start = 0; start < order.length && results.length < k; start += 100) {
        const batch = order.slice(start, start + 100);
        const eligible = filterCandidates(batch.map((index) => ids[index]));
        for (const index of batch) {
            if (results.length === k)
                break;
            if (eligible.has(ids[index]))
                results.push(result(index));
        }
    }
    return results;
}
/**
 * The k nearest neighbours of an already-indexed entry, by its stored vector —
 * no re-embedding, no network. Returns [] when the entry has no stored
 * vector. Unscoped, the entry itself is typically returned with distance ~0;
 * callers filter it out by id. A `scope` confines the neighbours to one
 * bundle's entries of one type, and `filterCandidates` keeps only the entries it
 * accepts (see {@link searchVec}).
 */
export function getNeighborsByEntryId(db, id, k, scope, filterCandidates) {
    const row = db.prepare("SELECT embedding FROM embeddings WHERE id = ?").get(id);
    if (!row || row.embedding.byteLength % 4 !== 0)
        return [];
    return searchVec(db, new Float32Array(row.embedding.slice().buffer), k, scope, filterCandidates);
}
/** Every stored vector of the index's current embedding model, by entry id. A vector of another model is left out. */
export function listCurrentEmbeddings(db) {
    const current = modelPredicate(db, currentEmbeddingModel(db));
    const rows = db.prepare(`SELECT id, embedding FROM embeddings WHERE ${current.sql}`).all(...current.params);
    const vectors = new Map();
    for (const row of rows)
        if (row.embedding.byteLength % 4 === 0)
            vectors.set(row.id, new Float32Array(row.embedding.slice().buffer));
    return vectors;
}
/** Whether the entry has a stored vector (what {@link getNeighborsByEntryId} reads). */
export function hasStoredEmbedding(db, id) {
    return db.prepare("SELECT 1 FROM embeddings WHERE id = ?").get(id) != null;
}
/**
 * Every entry that has no embedding row for `model` (any row when no model is
 * given), with its embedding input derived from the stored document
 * (`buildSearchText`, whose hash `upsertEntry` keeps in `entries.embed_hash`).
 * This is the embedding pass's cursor: a row generated under another model
 * counts as missing and is replaced when the entry is re-embedded, so a model
 * change re-embeds incrementally and an interrupted pass resumes where it
 * stopped. A row whose `document_json` does not parse has no text to embed
 * and is left out.
 */
export function getAllEntriesForEmbedding(db, entryIds, model) {
    const select = "SELECT e.id, e.document_json AS documentJson, e.item_ref AS itemRef, e.file_path AS filePath FROM entries e";
    const current = modelPredicate(db, model, "b");
    const missing = `NOT EXISTS (SELECT 1 FROM embeddings b WHERE b.id = e.id AND ${current.sql})`;
    const rows = [];
    if (entryIds === undefined) {
        rows.push(...db.prepare(`${select} WHERE ${missing} ORDER BY e.id`).all(...current.params));
    }
    else {
        const targets = [...new Set(entryIds)].sort((left, right) => left - right);
        for (let offset = 0; offset < targets.length; offset += SQLITE_CHUNK_SIZE) {
            const chunk = targets.slice(offset, offset + SQLITE_CHUNK_SIZE);
            const placeholders = chunk.map(() => "?").join(",");
            rows.push(...db
                .prepare(`${select} WHERE e.id IN (${placeholders}) AND ${missing} ORDER BY e.id`)
                .all(...chunk, ...current.params));
        }
    }
    const entries = [];
    for (const { documentJson, ...row } of rows) {
        const searchText = searchTextOf(documentJson);
        if (searchText !== undefined)
            entries.push({ ...row, searchText });
    }
    return entries;
}
/** An entry's embedding input from its stored document, or undefined when the document does not parse. */
function searchTextOf(documentJson) {
    try {
        return buildSearchText(JSON.parse(documentJson));
    }
    catch {
        return undefined;
    }
}
/**
 * The embedding input and stored vector bytes of every entry whose vector is
 * served as `model`'s (what `akm index --export-vectors` writes). Unlabelled
 * rows count only when `model` is the model the index currently serves, so
 * they are never stamped with a model they were not generated under.
 */
export function listEmbeddedSearchTexts(db, model) {
    const serving = currentEmbeddingModel(db) === model;
    if (!serving && !hasModelColumn(db))
        return [];
    const current = serving ? modelPredicate(db, model, "b") : { sql: "b.model = ?", params: [model] };
    const rows = db
        .prepare(`SELECT e.document_json AS documentJson, b.embedding AS embedding FROM entries e JOIN embeddings b ON b.id = e.id WHERE ${current.sql} ORDER BY e.id`)
        .all(...current.params);
    const out = [];
    for (const { documentJson, embedding } of rows) {
        const searchText = searchTextOf(documentJson);
        if (searchText !== undefined)
            out.push({ searchText, embedding });
    }
    return out;
}
/** Stored embedding rows — for `model` when given, otherwise every row. */
export function getEmbeddingCount(db, model) {
    const current = modelPredicate(db, model);
    const row = db.prepare(`SELECT COUNT(*) AS cnt FROM embeddings WHERE ${current.sql}`).get(...current.params);
    return row.cnt;
}
